"use client";
/* Loaf, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Loaf(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("loaf"); }, []);
  return React.createElement("piix-sprite", { "name": "loaf", ...piixAttrs(props) });
}

export default Loaf;
